(7310028,0,'공포으 ㅣ뱀파이어(사망시)',0,'이..이럴수가..내 마성의 힘을 이겨내다니...','','','','',0,0,0,0,0,0),
(7310056,0,'어둠의 나이트 발드(사망시)',0,'나를 쓰러트린 것이 그대들인가? 나의 왕을 구해다오...부탁하지...','','','','',0,0,0,0,0,0),
(7320096,0,'오토 허수아비',0,'여러분들은 오토에 확인되서, 압류 조취 됩니다.','문의는 \'메티스\' 편지주시길 바랍니다.','','','',100000,0,0,1,100000,0),
(7320207,0,'스타벌룬(신규사냥터)',0,'.라이트 도움말로 화면을 밝게 변경이 가능합니다','','','','',10000,0,0,1,10000,0),
(7320208,0,'제씨(신규사냥터)',0,'.좌표 기능으로 낑김/팅김 해결이 가능합니다','','','','',10000,0,0,1,10000,0),
(7320206,0,'스피리드(신규사냥터)',0,'레벨82가 되면 자동으로 마을로 귀환 됩니다.','','','','',10000,0,0,1,10000,0),
(7320209,0,'범도르(신규사냥터)',0,'기란감옥 던전 외에 시간 타임별 사냥터 종류가 몇개있으니 서버정보책을 확인하세요!','','','','',10000,0,0,1,10000,0),
(900104,0,'호외 소년',0,'VPN사용이 확인 될 경우 경고없이 BAN처리 될 수 있습니다.','카톡 #쿠팡서버 통해고정신청 및 후기이벤트보상을 획득 하시면 플레이에 도움이 됩니다.','운영문의 카카오톡 : #쿠팡서버','VPN사용이 확인 될 경우 경고없이 BAN처리 될 수 있습니다.','카톡 #쿠팡서버 통해고정신청 및 후기이벤트보상을 획득 하시면 플레이에 도움이 됩니다.',10000,0,0,1,60000,0),
(991155,0,'수호썸남',0,'어서와 수호서버는 처음이지?','우선 수호서버 가이드북을 꼭 읽어!','수호서버는 성드립/패드립/서버비방외에 유저 자율 이야!','대신 2계정 초과하거나 VPN사용하다 경고없이 BAN처리 될 수 있어!','수호서버에서 찐 리니지로 즐겨봐! 니가 찾던 곳 여기 맞아!',10000,0,0,1,20000,0),
(991156,0,'수호후원썸남',0,'여기서 팅기면 부캐릭으로 캐릭복구 주문서 사용해','여긴 잘 팅겨! 팅기면 부캐릭으로 캐릭복구 주문서 사용해','여기서 팅기면 부캐릭으로 캐릭복구 주문서 사용해','여긴 잘 팅겨! 팅기면 부캐릭으로 캐릭복구 주문서 사용해','여기서 팅기면 부캐릭으로 캐릭복구 주문서 사용해',10000,0,0,1,20000,0),
(991157,0,'수호썸녀',0,'CHU~','CHU~','CHU~','CHU~','CHU~',10000,0,0,1,20000,0),
(1010576,0,'암흑룡 질리언',0,'여기가 당신의 마지막이 될 것입니다.','이 악몽,당신도 꾸게 해주죠!','하지만, 칠흑의 밤은 지속될 겁니다.','','',10000,0,0,0,0,0),
(1010577,0,'암흑룡 조우',0,'그 살,그 피... 모두 쓸모있게 써 주지!','운명은 널 파멸로 이끌 것이다!','','','',10000,0,0,0,0,0),
(1010578,0,'암흑룡 아툰',0,'이 검으로 처단해주지!','숨이 붙어 있는 한...절대 물러나지 않는다!','','','',10000,0,0,0,0,0),
(1010573,0,'알비노 피닉스',0,'추악한 자들에게 심판을!','','','','',0,0,0,0,0,0),
(1010572,0,'알비노 데몬',0,'모조리 불태워주지!','너도 지옥으로 끌고 들어가지!','','','',0,0,0,0,0,0),
(1010574,0,'알비노 유니콘',0,'모두 되갚아줄 날만 기다렸다!','어차피 너희는 내 발 아래에 있다!','','','',0,0,0,0,0,0);
